  -H "Authorization: Bearer CiRuYTEtZjUzMC1kN2ViLTQ2MDgtODhlYS03MmIyOGIxMzhlMDMQ4fyjBBiIvpIdKhkABeaRgpmK_B7Y8iacoC-Pc3USZrpnQ7nBSgNuYTE" \
  -H "Content-Type: application/json" \
  -d '{
    "filterGroups": [
      {
        "filters": [
          {
            "propertyName": "partner_list_email",
            "operator": "EQ",
            "value": "true"
